import React from 'react';
import { useNavigate } from 'react-router-dom';
import { FaMars, FaVenus, FaRegImage } from 'react-icons/fa';
import './PetCard.css';

const PetCard = ({ pet }) => {
    const navigate = useNavigate();

    // ✅ SMART IMAGE LOGIC:
    // 1. Check if the new 'images' list exists and has at least one image.
    // 2. If yes, use the first image as the thumbnail.
    // 3. If no, fall back to the old 'imageUrl' field.
    // 4. If both are missing, use a placeholder.
    const mainImage = (pet.images && pet.images.length > 0)
        ? pet.images[0]
        : (pet.imageUrl || "");

    return (
        <div className="pet-card" onClick={() => navigate(`/pet/${pet.id}`)}>
            <div className="pet-image-container">
                {mainImage ? (
                    <img
                        src={mainImage}
                        alt={pet.name}
                        className="pet-image"
                        onError={(e) => {
                            e.target.onerror = null;
                            e.target.src = "https://via.placeholder.com/300?text=Error+Loading";
                        }}
                    />
                ) : (
                    // Show a nice icon if there is absolutely no image
                    <div className="no-image-placeholder">
                        <FaRegImage size={40} color="#cbd5e1" />
                    </div>
                )}
            </div>

            <div className="pet-info">
                <div className="pet-header">
                    <h3 className="pet-name">{pet.name}</h3>
                    <span className="gender-icon">
                        {pet.gender === 'Male' ? <FaMars color="#3b82f6"/> : <FaVenus color="#ec4899"/>}
                    </span>
                </div>
                <div className="pet-details">
                    <span className="pet-breed">{pet.breed}</span>
                    <span className="pet-age-dot">•</span>
                    <span className="pet-age">{pet.age} years</span>
                </div>
            </div>
        </div>
    );
};

export default PetCard;
